Problem:
A fitness trainer is scheduling her client to eat more fruits and vegetables to meet their vitamin and fiber requirements. A pack of fruits contains 4 units of vitamin and 7.5 units of fiber. A pack of vegetables contains 7 units of vitamin and 5 units of fiber. The client must meet their weekly minimum requirements of 100 units of vitamin and 120 units of fiber. In addition, because fruits contain more hydration, the client must eat at least twice as many packs of fruits as packs of vegetables. If a pack of fruits contains 3 units of sugar and a pack of vegetables contains 1 unit of sugar, how many of packs of each should the client consume to minimize their sugar intake?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "fruit packs",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "vegetable packs",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "fruit packs",
     "coef": 3.0
    },
    {
     "var": "vegetable packs",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "vitamin",
    "terms": [
     {
      "var": "fruit packs",
      "coef": 4.0
     },
     {
      "var": "vegetable packs",
      "coef": 7.0
     }
    ],
    "sense": ">=",
    "rhs": 100.0
   },
   {
    "name": "fiber",
    "terms": [
     {
      "var": "fruit packs",
      "coef": 7.5
     },
     {
      "var": "vegetable packs",
      "coef": 5.0
     }
    ],
    "sense": ">=",
    "rhs": 120.0
   },
   {
    "name": "hydration",
    "terms": [
     {
      "var": "fruit packs",
      "coef": 1.0
     },
     {
      "var": "vegetable packs",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 49.0,
  "values": {
   "fruit packs": 14.0,
   "vegetable packs": 7.0
  },
  "binding": [
   "hydration"
  ],
  "slack": {
   "vitamin": 5.0,
   "fiber": 20.0,
   "hydration": 0.0
  },
  "shadow_prices": null,
  "limits": {
   "vitamin": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "fiber": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "hydration": {
    "dropped_improves": true,
    "loosened_improves": true
   }
  }
 }
}
